import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';

const ProblemDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { token } = useAuth();
  const [problem, setProblem] = useState(null);
  const [code, setCode] = useState('');
  const [language, setLanguage] = useState('java');
  const [output, setOutput] = useState('');
  const [error, setError] = useState('');
  const [submissionResult, setSubmissionResult] = useState(null);
  const [runLoading, setRunLoading] = useState(false);
  const [submitLoading, setSubmitLoading] = useState(false);
  const [customInput, setCustomInput] = useState('');

  const templates = {
    java: `import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Write your code here
        
    }
}`,
    cpp: `#include <bits/stdc++.h>
using namespace std;

int main() {
    // Write your code here
    
    return 0;
}`
  };

  const fetchProblem = useCallback(async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/problems/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblem(response.data.problem);
    } catch (error) {
      console.error('Error fetching problem:', error);
      navigate('/problems');
    }
  }, [id, token, navigate]);

  useEffect(() => {
    fetchProblem();
    setCode(templates[language]);
  }, [language, fetchProblem]);

  const handleRun = async () => {
    setRunLoading(true);
    setOutput('');
    setError('');
    setSubmissionResult(null);

    try {
      const response = await axios.post('http://localhost:5000/api/submissions/run', {
        problemId: id,
        code,
        language,
        input: customInput || problem?.sampleInput
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.error) {
        setError(response.data.error);
      } else {
        setOutput(response.data.output || '✅ Program executed successfully (no output)');
      }
    } catch (error) {
      setError(error.response?.data?.message || 'Error running code. Please try again.');
    } finally {
      setRunLoading(false);
    }
  };

  const handleSubmit = async () => {
    setSubmitLoading(true);
    setOutput('');
    setError('');
    setSubmissionResult(null);

    try {
      const response = await axios.post('http://localhost:5000/api/submissions/submit', {
        problemId: id,
        code,
        language
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      setSubmissionResult(response.data);
      
      if (response.data.status === 'accepted') {
        setOutput('🎉 All test cases passed! Great job!');
      } else {
        setOutput(`⚠️ ${response.data.passedTestCases}/${response.data.totalTestCases} test cases passed`);
      }
    } catch (error) {
      setError(error.response?.data?.message || 'Error submitting code. Please try again.');
    } finally {
      setSubmitLoading(false);
    }
  };

  if (!problem) {
    return (
      <div style={styles.loadingContainer}>
        <div className="loading-spinner"></div>
        <p>Loading problem...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div style={styles.headerLeft}>
          <h1 style={styles.problemTitle}>{problem.title}</h1>
          <div style={styles.problemMeta}>
            <span style={{
              ...styles.difficultyBadge,
              backgroundColor: problem.difficulty === 'Easy' ? '#28a745' :
                             problem.difficulty === 'Medium' ? '#ffc107' : '#dc3545'
            }}>
              {problem.difficulty || 'Easy'}
            </span>
            <span style={styles.problemId}>#{problem._id}</span>
          </div>
        </div>
        <button onClick={() => navigate('/problems')} style={styles.backButton}>
          ← Back to Problems
        </button>
      </div>

      {/* Problem Description */}
      <div style={styles.descriptionCard}>
        <div style={styles.descriptionSection}>
          <h3>📖 Problem Statement</h3>
          <p>{problem.description}</p>
        </div>
        
        <div style={styles.sampleSection}>
          <div style={styles.sampleBox}>
            <h4>Sample Input:</h4>
            <pre>{problem.sampleInput}</pre>
          </div>
          <div style={styles.sampleBox}>
            <h4>Sample Output:</h4>
            <pre>{problem.sampleOutput}</pre>
          </div>
        </div>
        
        <div style={styles.constraints}>
          <h4>Constraints:</h4>
          <p>{problem.constraints}</p>
        </div>
      </div>

      {/* Code Editor */}
      <div style={styles.editorCard}>
        <div style={styles.editorControls}>
          <div style={styles.controlGroup}>
            <label style={styles.controlLabel}>Language:</label>
            <select
              value={language}
              onChange={(e) => {
                setLanguage(e.target.value);
                setCode(templates[e.target.value]);
              }}
              style={styles.select}
            >
              <option value="java">☕ Java</option>
              <option value="cpp">⚡ C++</option>
            </select>
          </div>
          <div style={styles.actionButtons}>
            <button
              onClick={handleRun}
              disabled={runLoading || submitLoading}
              style={styles.runButton}
            >
              {runLoading ? '⏳ Running...' : '▶ Run'}
            </button>
            <button
              onClick={handleSubmit}
              disabled={runLoading || submitLoading}
              style={styles.submitButton}
            >
              {submitLoading ? '⏳ Submitting...' : '📤 Submit'}
            </button>
          </div>
        </div>

        <textarea
          value={code}
          onChange={(e) => setCode(e.target.value)}
          style={styles.editor}
          spellCheck={false}
        />

        <div style={styles.inputOutputSection}>
          <div style={styles.inputGroup}>
            <h4>📝 Custom Input:</h4>
            <textarea
              value={customInput}
              onChange={(e) => setCustomInput(e.target.value)}
              style={styles.customInput}
              placeholder="Enter custom input here..."
              rows={3}
            />
          </div>
          <div style={styles.outputGroup}>
            <h4>📤 Output:</h4>
            <div style={styles.outputBox}>
              {error ? (
                <pre style={styles.errorOutput}>{error}</pre>
              ) : (
                <pre style={styles.successOutput}>{output || 'Run your code to see output'}</pre>
              )}
            </div>
          </div>
        </div>

        {/* Submission Results */}
        {submissionResult && (
          <div style={styles.resultSection}>
            <h3>📊 Submission Results</h3>
            <div style={{
              ...styles.resultSummary,
              ...(submissionResult.status === 'accepted' ? styles.resultAccepted : styles.resultFailed)
            }}>
              <div style={styles.resultScore}>
                Score: <strong>{submissionResult.score.toFixed(1)}%</strong>
              </div>
              <div>
                {submissionResult.passedTestCases} / {submissionResult.totalTestCases} Test Cases Passed
              </div>
              <div style={styles.resultStatus}>
                Status: {submissionResult.status === 'accepted' ? '✅ Accepted' : '❌ Wrong Answer'}
              </div>
            </div>

            <div style={styles.testCasesDetails}>
              <h4>Test Case Details:</h4>
              {submissionResult.results.map((result, index) => (
                <div key={index} style={{
                  ...styles.testCaseItem,
                  ...(result.passed ? styles.testCasePassed : styles.testCaseFailed)
                }}>
                  <div style={styles.testCaseHeader}>
                    <span>Test Case {index + 1}</span>
                    <span>{result.passed ? '✅ Passed' : '❌ Failed'}</span>
                  </div>
                  {!result.passed && (
                    <div style={styles.testCaseDetails}>
                      <div>Expected: <pre>{result.expected}</pre></div>
                      <div>Got: <pre>{result.output || 'No output'}</pre></div>
                      {result.error && <div>Error: <pre style={styles.testError}>{result.error}</pre></div>}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f0f2f5',
    padding: '20px',
    maxWidth: '1400px',
    margin: '0 auto'
  },
  loadingContainer: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh'
  },
  header: {
    background: 'white',
    padding: '20px 30px',
    borderRadius: '12px',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '20px'
  },
  headerLeft: {
    flex: 1
  },
  problemTitle: {
    fontSize: '28px',
    marginBottom: '8px',
    color: '#1a1a2e'
  },
  problemMeta: {
    display: 'flex',
    gap: '15px',
    alignItems: 'center'
  },
  difficultyBadge: {
    padding: '4px 14px',
    borderRadius: '20px',
    color: 'white',
    fontSize: '12px',
    fontWeight: '600'
  },
  problemId: {
    color: '#999',
    fontSize: '14px'
  },
  backButton: {
    padding: '8px 20px',
    background: '#6c757d',
    color: 'white',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '14px'
  },
  descriptionCard: {
    background: 'white',
    padding: '25px 30px',
    borderRadius: '12px',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)',
    marginBottom: '20px'
  },
  descriptionSection: {
    marginBottom: '20px',
    lineHeight: '1.8'
  },
  sampleSection: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: '20px',
    marginBottom: '20px'
  },
  sampleBox: {
    background: '#f8f9fa',
    padding: '15px',
    borderRadius: '8px'
  },
  constraints: {
    background: '#fff3cd',
    padding: '15px',
    borderRadius: '8px'
  },
  editorCard: {
    background: 'white',
    padding: '25px',
    borderRadius: '12px',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)'
  },
  editorControls: {
