    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '15px',
    flexWrap: 'wrap',
    gap: '10px'
  },
  controlGroup: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px'
  },
  controlLabel: {
    fontWeight: '500',
    color: '#333'
  },
  select: {
    padding: '8px 15px',
    border: '2px solid #e1e5e9',
    borderRadius: '6px',
    fontSize: '14px',
    background: 'white'
  },
  actionButtons: {
    display: 'flex',
    gap: '10px'
  },
  runButton: {
    padding: '8px 24px',
    background: '#28a745',
    color: 'white',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: '500'
  },
  submitButton: {
    padding: '8px 24px',
    background: '#1a73e8',
    color: 'white',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: '500'
  },
  editor: {
    width: '100%',
    minHeight: '350px',
    fontFamily: 'monospace',
    fontSize: '14px',
    padding: '15px',
    border: '2px solid #e1e5e9',
    borderRadius: '8px',
    background: '#1e1e1e',
    color: '#d4d4d4',
    resize: 'vertical',
    tabSize: 4
  },
  inputOutputSection: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
