    gap: '8px'
  },
  customInput: {
    padding: '10px',
    border: '2px solid #e1e5e9',
    borderRadius: '6px',
    fontFamily: 'monospace',
    fontSize: '14px',
    resize: 'vertical'
  },
  outputGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '8px'
  },
  outputBox: {
    padding: '10px',
    border: '2px solid #e1e5e9',
    borderRadius: '6px',
    minHeight: '80px',
    background: '#f8f9fa',
    overflow: 'auto'
  },
  successOutput: {
    margin: 0,
    color: '#28a745',
    fontFamily: 'monospace',
    fontSize: '14px',
    whiteSpace: 'pre-wrap'
  },
  errorOutput: {
    margin: 0,
    color: '#dc3545',
    fontFamily: 'monospace',
    fontSize: '14px',
    whiteSpace: 'pre-wrap'
  },
  resultSection: {
    marginTop: '20px',
    padding: '20px',
    border: '2px solid #e1e5e9',
    borderRadius: '8px'
  },
  resultSummary: {
    padding: '15px',
    borderRadius: '6px',
    marginBottom: '15px'
  },
  resultAccepted: {
    background: '#d4edda',
    border: '1px solid #c3e6cb'
  },
  resultFailed: {
    background: '#f8d7da',
    border: '1px solid #f5c6cb'
  },
  resultScore: {
    fontSize: '18px'
  },
  resultStatus: {
    fontWeight: '600',
    marginTop: '5px'
  },
  testCasesDetails: {
    marginTop: '10px'
  },
  testCaseItem: {
    padding: '12px',
    borderRadius: '6px',
    marginBottom: '8px',
    border: '1px solid #e1e5e9'
  },
  testCasePassed: {
    background: '#f8f9fa',
    borderLeft: '4px solid #28a745'
  },
  testCaseFailed: {
    background: '#fff5f5',
    borderLeft: '4px solid #dc3545'
  },
  testCaseHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    fontWeight: '500'
  },
  testCaseDetails: {
    marginTop: '8px',
    paddingTop: '8px',
    borderTop: '1px solid #e1e5e9'
  },
  testError: {
    color: '#dc3545'
  }
};

export default ProblemDetail;
